//
//  BXMarca.swift
//  BlaxxPontos · Design system "Embarque"
//
//  Wordmark "BlaXx" desenhado a partir dos SVG do web (blaxx/assets/marca/), sem imagem rasterizada:
//  - `.barra`        blaxx-wordmark-barra.svg        "Bla" branco + "Xx" neon (fundo escuro)   viewBox 40 28 817 158
//  - `.claro`        blaxx-wordmark-barra-claro.svg  "Bla" tinta + "Xx" neon com contorno tinta  viewBox 36 24 825 166
//  - `.logoCompleto` blaxx-logo-completo-justo.svg   B + BlaXx + REWARDS (fundo escuro)          viewBox 35 24 540 445
//  Nunca montar "Bla" + "Xx" com `Text`. Os assets antigos BlaxxWordmark/BlaxxWordmarkClaro/BlaxxLockup
//  deixam de ser usados pelo app novo.
//  Os `d=` abaixo foram copiados sem alteração dos arquivos do web (só caminhos absolutos M/L/C/Z).
//

import SwiftUI

struct BXWordmark: View {
    enum Variante: Sendable, CaseIterable {
        /// "Bla" branco + "Xx" neon, para a barra preta e a cabeça do recibo.
        case barra
        /// "Bla" tinta + "Xx" neon com contorno tinta, para fundo claro.
        case claro
        /// Símbolo B + BlaXx + REWARDS (rodapé, fundo escuro).
        case logoCompleto
    }

    let variante: Variante
    let altura: CGFloat

    /// barra: 114 x 22 na barra do topo; cabeça do recibo: altura 30; rodapé (logo completo): 80.
    init(_ variante: Variante = .barra, altura: CGFloat = 22) {
        self.variante = variante
        self.altura = altura
    }

    var body: some View {
        let caixa = BXMarcaDados.caixa(variante)
        BXSVGVista(elementos: BXMarcaDados.elementos(variante), caixa: caixa, corAtual: BXCor.tinta, tracoPadrao: 0)
            .frame(width: altura * caixa.width / caixa.height, height: altura)
            .accessibilityElement()
            .accessibilityLabel("BlaXx")
            .accessibilityAddTraits(.isImage)
    }
}

nonisolated enum BXMarcaDados {
    static func caixa(_ v: BXWordmark.Variante) -> CGRect {
        switch v {
        case .barra: return CGRect(x: 40, y: 28, width: 817, height: 158)
        case .claro: return CGRect(x: 36, y: 24, width: 825, height: 166)
        case .logoCompleto: return CGRect(x: 35, y: 24, width: 540, height: 445)
        }
    }

    static func elementos(_ v: BXWordmark.Variante) -> [BXSVG.Elemento] {
        switch v {
        case .barra: return barra
        case .claro: return claro
        case .logoCompleto: return logoCompleto
        }
    }

    static let barra: [BXSVG.Elemento] = BXSVG.elementos(svgBarra, tracoPadrao: false)
    static let claro: [BXSVG.Elemento] = BXSVG.elementos(svgClaro, tracoPadrao: false)
    static let logoCompleto: [BXSVG.Elemento] = BXSVG.elementos(svgLogoCompleto, tracoPadrao: false)

